// src/pages/CompanyBasedTechMocs.jsx
import React, { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import NavBar from "../NavBar.jsx"; // path is correct

// Companies taken ONLY from your doc sets (plus requested additions)
// Product-Based
const productCompanies = [
  "Facebook (Meta)",   // NEW
  "Amazon",            // NEW
  "Netflix",           // NEW
  "Apple",
  "Alphabet (Google)",
  "Microsoft",
  "Flipkart",
  "Uber",
  "IBM",
];

// Service-Based
const serviceCompanies = [
  "Tata Consultancy Services (TCS)",
  "Accenture",
  "Infosys",
  "Wipro",
  "HCLTech",
  "Tech Mahindra",
  "Capgemini",
  "Deloitte",
  "EY",
];

// Startups
const startupCompanies = [
 "Zepto",
  "Swiggy",
  "CRED",
  "PhonePe",
  "Nykaa",
  "Meesho",
  "Paytm",
  "Razorpay",
  "Blinkit",
];

const slugify = (s) =>
  (s || "")
    .toLowerCase()
    .replace(/[\(\)]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");

export default function CompanyBasedTechMocs() {
  const navigate = useNavigate();
  const [mode, setMode] = useState("root"); // root | product | service | startup

  const { title, list, allLabel, typeKey } = useMemo(() => {
    if (mode === "product")
      return {
        title: "Product Based Tech Companies",
        list: productCompanies,
        allLabel: "All Product Based Tech Companies",
        typeKey: "product",
      };
    if (mode === "service")
      return {
        title: "Service Based Tech Companies",
        list: serviceCompanies,
        allLabel: "All Service Based Tech Companies",
        typeKey: "service",
      };
    if (mode === "startup")
      return {
        title: "Top Startup Companies",
        list: startupCompanies,
        allLabel: "All Startup Companies",
        typeKey: "startup",
      };
    return { title: "", list: [], allLabel: "", typeKey: "" };
  }, [mode]);

  const goToTechSelection = (e, { display, slugHint }) => {
    e?.preventDefault?.();
    e?.stopPropagation?.();
    navigate("/technology-selection", {
      state: {
        company: display,
        slug: slugHint || slugify(display),
        flow: "company",
        allType: ["product", "service", "startup"].includes(typeKey)
          ? typeKey
          : undefined,
      },
    });
  };

  const Card = ({ title, subtitle, onClick }) => (
    <button
      type="button"
      onClick={onClick}
      className="rounded-2xl border border-white/10 px-6 py-6 text-left bg-white/[0.04] hover:bg-white/[0.08] transition relative overflow-hidden"
    >
      <div
        className="pointer-events-none absolute -top-20 -right-20 w-72 h-72 rounded-full blur-3xl opacity-30"
        style={{
          background: `linear-gradient(135deg, rgba(255,255,255,.08), rgba(255,255,255,.02))`,
        }}
      />
      <div className="text-2xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-emerald-600">
        {title}
      </div>
      <div className="mt-1 text-white/70">{subtitle}</div>
    </button>
  );

  return (
    <div className="min-h-screen bg-[#0f172a] text-white flex flex-col">
      <NavBar />
      <main className="flex-1 w-full py-10 md:py-16">
        <div className="max-w-6xl mx-auto px-4 md:px-6">
          <h1 className="text-3xl md:text-4xl font-black tracking-tight mb-6">
            Company Based Tech Mocks
          </h1>

          {mode === "root" ? (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
              <Card
                title="Product Based Tech Companies"
                subtitle="Top product orgs & drills"
                onClick={() => setMode("product")}
              />
              <Card
                title="Service Based Tech Companies"
                subtitle="Consulting & delivery patterns"
                onClick={() => setMode("service")}
              />
              <Card
                title="Startups"
                subtitle="Zero-to-one pace & ownership"
                onClick={() => setMode("startup")}
              />
            </div>
          ) : (
            <>
              <div className="mb-6 flex items-center justify-between">
                <h2 className="text-2xl font-bold">{title}</h2>
                <div className="flex gap-2">
                  <button
                    className="px-3 py-1.5 rounded-lg bg-white/10 border border-white/10 hover:bg-white/20"
                    onClick={() => setMode("root")}
                  >
                    Back
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {list.map((name) => (
                  <button
                    key={name}
                    type="button"
                    className="rounded-xl border border-white/10 bg-white/[0.04] hover:bg-white/[0.08] text-left p-5"
                    onClick={(e) => goToTechSelection(e, { display: name })}
                  >
                    <div className="text-lg font-semibold">{name}</div>
                    <div className="text-sm text-white/60">Click to choose tech</div>
                  </button>
                ))}
              </div>

              {/* “All … Companies” button UNDER the list */}
              <div className="mt-6">
                <button
                  type="button"
                  onClick={(e) =>
                    goToTechSelection(e, {
                      display:
                        mode === "product"
                          ? "All Product Based Tech Companies"
                          : mode === "service"
                          ? "All Service Based Tech Companies"
                          : "All Startup Companies",
                      slugHint: `${mode}-all`,
                    })
                  }
                  className="rounded-xl px-4 py-3 border border-white/10 bg-white/[0.04] hover:bg-white/[0.08]"
                >
                  {allLabel}
                </button>
              </div>
            </>
          )}
        </div>
      </main>
    </div>
  );
}
