import React, { useMemo, useRef } from "react";

const LPA_MAX = 100;
const clamp = (v, min, max) => Math.min(Math.max(v, min), max);

// NOTE: product.secondStart is 50 now (not 25)
const HALF_RULES = {
  product:   { firstMax: 50, secondStart: 50, ticks: [0,25,50,100], sub: "0–25 • 25–50 • 50–100" },
  service:   { firstMax: 10, secondStart: 10, ticks: [0,5,10,100],   sub: "0–5 • 5–10 • 10–100" },
  startup:   { firstMax: 16, secondStart: 16, ticks: [0,8,16,100],   sub: "0–8 • 8–16 • 16–100" },
  universal: { firstMax: 16, secondStart: 16, ticks: [0,8,16,100],   sub: "0–8 • 8–16 • 16–100" },
};

export default function PackageDial({ companyType, value, onChange, size = 300 }) {
  const ref = useRef(null);

  // we keep a half lock only while dragging for consistent feel
  const activeHalfRef = useRef(null); // 'first' | 'second' during drag (product only)

  const rules = HALF_RULES[companyType] || HALF_RULES.universal;
  const { firstMax, secondStart } = rules;

  const thickness = 16;
  const r = (size - thickness) / 2;
  const c = size / 2;

  const ticks = useMemo(() => rules.ticks.map(v => ({ v, label: String(v) })), [rules]);
  const subLabel = rules.sub;
  const primaryLabel = `${Math.round(value)} LPA`;

  /* ---------- mappings ---------- */

  // FIRST HALF: 0..firstMax  ->  -90..+90
  const angleFromValueFirst = (v) => {
    const vv = clamp(v, 0, firstMax);
    const t = vv / (firstMax || 1);
    return -90 + t * 180;
  };
  const valueFromAngleFirst = (ang) => {
    const a = clamp(ang, -90, 90);
    const t = (a + 90) / 180;
    return clamp(Math.round(t * firstMax), 0, firstMax);
  };

  // SECOND HALF: secondStart..100  ->  +90..+270
  const angleFromValueSecond = (v) => {
    const vv = clamp(v, secondStart, LPA_MAX);
    const t = (vv - secondStart) / ((LPA_MAX - secondStart) || 1);
    return 90 + t * 180;
  };
  const valueFromAngleSecond = (ang) => {
    const a = clamp(ang, 90, 270);
    const t = (a - 90) / 180;
    return clamp(Math.round(secondStart + t * (LPA_MAX - secondStart)), secondStart, LPA_MAX);
  };

  const isProduct = companyType === "product";
  // no overlap anymore on product: secondStart === firstMax (50)
  const renderHalf =
    value <= firstMax && activeHalfRef.current !== "second" ? "first" : "second";

  const handleAngleDeg =
    renderHalf === "first"
      ? angleFromValueFirst(Math.min(value, firstMax))
      : angleFromValueSecond(Math.max(value, secondStart));

  /* ---------- interaction ---------- */

  const centerAngle = (clientX, clientY) => {
    const rect = ref.current.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const dx = clientX - cx;
    const dy = clientY - cy;
    return (Math.atan2(dy, dx) * 180) / Math.PI; // −180..+180, 0° at right
  };

  const interpretAngle = (phi) => {
    // normalize to [0,360)
    const deg = ((phi + 360) % 360);

    // For all types:
    //   90..270  -> second half mapping
    //   else     -> first half mapping (but convert >270 into [-90,0) for first)
    if (deg >= 90 && deg <= 270) return valueFromAngleSecond(deg);
    const firstDeg = deg > 270 ? deg - 360 : deg; // => [-90,90)
    return valueFromAngleFirst(firstDeg);
  };

  const onPointerDown = (e) => {
    e.preventDefault();
    const t0 = e.touches?.[0] || e;
    const start = centerAngle(t0.clientX, t0.clientY);
    const startDeg = ((start + 360) % 360);

    // product: remember which half you grabbed so it doesn’t “jump” while dragging across 90°
    activeHalfRef.current = isProduct ? (startDeg >= 90 && startDeg <= 270 ? "second" : "first") : null;

    const move = (ev) => {
      const t = ev.touches?.[0] || ev;
      const phi = centerAngle(t.clientX, t.clientY);
      onChange(interpretAngle(phi));
    };
    const up = () => {
      activeHalfRef.current = null;
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("touchmove", move);
      window.removeEventListener("touchend", up);
    };

    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("touchmove", move, { passive: false });
    window.addEventListener("touchend", up);

    // initial update
    onChange(interpretAngle(start));
  };

  const onKeyDown = (e) => {
    if (["ArrowLeft","ArrowDown"].includes(e.key)) { e.preventDefault(); onChange(Math.max(0, value - 1)); }
    else if (["ArrowRight","ArrowUp"].includes(e.key)) { e.preventDefault(); onChange(Math.min(LPA_MAX, value + 1)); }
    else if (e.key === "Home") { e.preventDefault(); onChange(0); }
    else if (e.key === "End")  { e.preventDefault(); onChange(LPA_MAX); }
  };

  /* ---------- drawing ---------- */
  const arc = (a0, a1) => {
    const A0 = (a0 * Math.PI) / 180, A1 = (a1 * Math.PI) / 180;
    const x1 = c + r * Math.cos(A0), y1 = c + r * Math.sin(A0);
    const x2 = c + r * Math.cos(A1), y2 = c + r * Math.sin(A1);
    const largeArc = Math.abs(a1 - a0) > 180 ? 1 : 0;
    return `M ${x1} ${y1} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2}`;
  };

  const bg = [
    { a0: -90, a1:  90 }, // first half
    { a0:  90, a1: 270 }, // second half
  ];

  const firstEnd  = angleFromValueFirst(Math.min(value, firstMax));
  const hasSecond = value >= secondStart;
  const secondEnd = hasSecond ? angleFromValueSecond(value) : null;

  const angleForTick = (v) => {
    if (v <= firstMax)    return angleFromValueFirst(v);
    if (v >= secondStart) return angleFromValueSecond(v);
    return angleFromValueFirst(firstMax);
  };

  const rad = (handleAngleDeg * Math.PI) / 180;
  const hx = c + r * Math.cos(rad);
  const hy = c + r * Math.sin(rad);

  return (
    <div className="inline-flex items-center justify-center">
      <svg
        ref={ref}
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="select-none touch-none cursor-pointer"
        onPointerDown={onPointerDown}
        onTouchStart={onPointerDown}
        role="slider"
        aria-valuemin={0}
        aria-valuemax={LPA_MAX}
        aria-valuenow={value}
        tabIndex={0}
        onKeyDown={onKeyDown}
        style={{ overflow: "visible" }}
      >
        {/* background halves */}
        {bg.map((s, i) => (
          <path key={i} d={arc(s.a0, s.a1)} stroke="rgba(255,255,255,.12)" strokeWidth={16} fill="none" />
        ))}

        {/* guides */}
        <path d={arc(-90, 90)}  stroke="rgba(255,255,255,.20)" strokeWidth={16} fill="none" />
        <path d={arc(90, 270)}  stroke="rgba(255,255,255,.10)" strokeWidth={16} fill="none" />

        {/* gradient */}
        <defs>
          <linearGradient id="gradProgress" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%"   stopColor="#22c55e" />
            <stop offset="33%"  stopColor="#eab308" />
            <stop offset="66%"  stopColor="#ef4444" />
            <stop offset="100%" stopColor="#a855f7" />
          </linearGradient>
        </defs>

        {/* progress arcs */}
        <path d={arc(-90, firstEnd)} stroke="url(#gradProgress)" strokeWidth={16} fill="none" strokeLinecap="round" />
        {hasSecond && (
          <path d={arc(90, secondEnd)} stroke="url(#gradProgress)" strokeWidth={16} fill="none" strokeLinecap="round" />
        )}

        {/* ticks */}
        {ticks.map((t, idx) => {
          const ang = angleForTick(t.v);
          const inner = r - 16 * 0.55;
          const outer = r + 16 * 0.12;
          const A = (ang * Math.PI) / 180;
          const x1 = c + inner * Math.cos(A), y1 = c + inner * Math.sin(A);
          const x2 = c + outer * Math.cos(A), y2 = c + outer * Math.sin(A);
          return (
            <g key={idx}>
              <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="rgba(255,255,255,.75)" strokeWidth="2" />
              <text
                x={c + (r + 16 * 0.6) * Math.cos(A)}
                y={c + (r + 16 * 0.6) * Math.sin(A)}
                fill="rgba(255,255,255,.95)" fontSize="12" fontWeight="700"
                textAnchor="middle" dominantBaseline="middle"
              >
                {t.label}
              </text>
            </g>
          );
        })}

        {/* handle */}
        <g>
          <circle cx={hx} cy={hy} r={16/1.5} fill="#fff" />
          <circle cx={hx} cy={hy} r={16/2.1} fill="none" stroke="rgba(0,0,0,.15)" />
        </g>

        {/* center text */}
        <text x={c} y={c - 6} fill="#fff" fontSize="26" fontWeight="900" textAnchor="middle" style={{ userSelect:"none" }}>
          {primaryLabel}
        </text>
        <text x={c} y={c + 22} fill="rgba(255,255,255,.9)" fontSize="12" textAnchor="middle" style={{ userSelect:"none" }}>
          {subLabel}
        </text>
      </svg>
    </div>
  );
}
