import React from "react";
import { LVL } from "./dialUtils";

export default function LevelRing({ value, onChange, size = 300 }) {
  const thickness = 16;
  const c = size / 2;
  const r = (size - thickness) / 2;
  const ri = r - thickness;
  const segments = [
    { key: "L1", label: "L1", sub: "Fresher L." },
    { key: "L2", label: "L2", sub: "FresherSkilled" },
    { key: "L3", label: "L3", sub: "Experienced" },
  ];
  const sweep = (2 * Math.PI) / segments.length;

  return (
    <div className="inline-flex items-center justify-center relative" style={{ overflow: "visible" }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="select-none" style={{ overflow: "visible" }}>
        <circle cx={c} cy={c} r={r} stroke="rgba(255,255,255,.12)" strokeWidth={thickness} fill="none" />
        {segments.map((s, i) => {
          const start = -Math.PI / 2 + i * sweep;
          const end = start + sweep;
          const largeArc = sweep > Math.PI ? 1 : 0;
          const x1 = c + r * Math.cos(start), y1 = c + r * Math.sin(start);
          const x2 = c + r * Math.cos(end),   y2 = c + r * Math.sin(end);
          const ix1 = c + ri * Math.cos(end), iy1 = c + ri * Math.sin(end);
          const ix2 = c + ri * Math.cos(start), iy2 = c + ri * Math.sin(start);
          const path = `M ${x1} ${y1} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2} L ${ix1} ${iy1} A ${ri} ${ri} 0 ${largeArc} 0 ${ix2} ${iy2} Z`;
          const active = value === s.key;

          const mid = start + sweep / 2;
          const ax = c + (r + thickness * 0.28) * Math.cos(mid);
          const ay = c + (r + thickness * 0.28) * Math.sin(mid);
          const bx = c + (r + thickness * 0.95) * Math.cos(mid);
          const by = c + (r + thickness * 0.95) * Math.sin(mid);

          const main = s.label || "";
          const sub = s.sub || "";
          const maxLen = Math.max(main.length, sub.length || 0);
          const w = Math.max(110, maxLen * 7.2), h = sub ? 36 : 22;

          return (
            <g key={s.key} onClick={() => onChange(s.key)} className="cursor-pointer">
              <path d={path} fill={active ? "rgba(168,85,247,.85)" : "rgba(255,255,255,.10)"} stroke={active ? "rgba(168,85,247,1)" : "rgba(255,255,255,.20)"} />
              <line x1={ax} y1={ay} x2={bx} y2={by} stroke={active ? "rgba(168,85,247,1)" : "rgba(255,255,255,.45)"} strokeWidth="1.6" />
              <rect x={bx - w/2} y={by - h/2} width={w} height={h} rx="9" ry="9"
                    fill={active ? "rgba(168,85,247,.18)" : "rgba(255,255,255,.10)"} stroke={active ? "rgba(168,85,247,.6)" : "rgba(255,255,255,.25)"} />
              <text x={bx} y={by - (sub ? 4 : 0)} fill="#fff" fontSize="12" fontWeight="700" textAnchor="middle" dominantBaseline="middle">{main}</text>
              {sub ? <text x={bx} y={by + 10} fill="rgba(255,255,255,.9)" fontSize="10" textAnchor="middle" dominantBaseline="middle">{sub}</text> : null}
            </g>
          );
        })}
        <text x={c} y={c - 4} fill="#fff" fontSize="16" fontWeight="900" textAnchor="middle">{LVL[value].label}</text>
        <text x={c} y={c + 16} fill="rgba(255,255,255,.9)" fontSize="11" textAnchor="middle">Difficulty</text>
      </svg>
    </div>
  );
}
