/* Shared helpers & constants for the SelectPackage flow */

export const PRODUCT = ["Apple","Microsoft","Alphabet (Google)","Amazon","Meta","NVIDIA","Samsung Electronics","Oracle","Adobe","Salesforce"];
export const SERVICE = ["Accenture","Tata Consultancy Services (TCS)","Infosys","Cognizant","Wipro","Capgemini","IBM Consulting","HCLTech","DXC Technology","Tech Mahindra"];
export const STARTUP = ["Stripe","SpaceX","Databricks","Canva","Revolut","Notion","Figma","Brex","Discord","OpenAI"];

export function detectType({ company, scope, allType, origin }) {
  const name = (company || "").toLowerCase();
  if (allType) return allType;
  if (scope && ["product","service","startup"].includes(scope)) return scope;
  if (origin === "universal" || name.includes("universal")) return "universal";
  if (name.includes("all product")) return "product";
  if (name.includes("all service")) return "service";
  if (name.includes("startup")) return "startup";
  if (PRODUCT.map(s=>s.toLowerCase()).includes(name)) return "product";
  if (SERVICE.map(s=>s.toLowerCase()).includes(name)) return "service";
  if (STARTUP.map(s=>s.toLowerCase()).includes(name)) return "startup";
  return "universal";
}

