export function bandIndexFor(type, v) {
  switch (type) {
    case "product":   return (v <= 25) ? 0 : (v <= 50) ? 1 : 2;
    case "service":   return (v <= 5)  ? 0 : (v <= 10) ? 1 : 2;
    case "startup":   return (v <= 8)  ? 0 : (v <= 16) ? 1 : 2;
    case "universal": return (v <= 8)  ? 0 : (v <= 16) ? 1 : 2;
    default:          return 0;
  }
}
export const bandByIndex = (type, i) => (BANDS[type] || BANDS.universal)[i];

