export const pkgTicksFor = (type) =>
  (type==="product"   ? [0,25,50,75,100]
  : type==="service"  ? [0,5,10,100]
  : type==="startup"  ? [0,8,16,100]
                      : [0,7,14,100]) // universal
  .map(v => ({ v, label: String(v) }));

export const pkgSubFor = (type) =>
  (type==="product"   ? "0–25 • 25–50 • 50–100"
  : type==="service"  ? "0–5 • 5–10 • 10–100"
  : type==="startup"  ? "0–8 • 8–16 • 16–100"
                      : "0–7 • 7–14 • 14–100");
