// src/components/launch/sections/ProductsSection.jsx
import React from "react";
import { Link } from "react-router-dom";
import Section from "../Section.jsx";

function CTA({ to = "/tools/resume-builder?mode=analyze", label = "Open" }) {
  return (
    <Link
      to={to}
      className="inline-flex items-center px-3 py-1.5 rounded-full
                 bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400
                 hover:from-blue-300 hover:via-blue-400 hover:to-blue-500
                 text-black font-semibold text-sm transition
                 focus:outline-none focus:ring-2 focus:ring-blue-300/70
                 focus:ring-offset-2 focus:ring-offset-transparent"
      aria-label={label}
    >
      {label}
      <span className="ml-1">→</span>
    </Link>
  );
}

function ProductCard({ item }) {
  return (
    <div
      role="article"
      className="product-card rounded-2xl bg-white/8 border border-white/10 px-6 py-6
                 transition min-h-[160px] flex flex-col items-center text-center
                 hover:bg-white/10 focus-within:bg-white/12"
    >
      <div className="text-2xl leading-none select-none opacity-90 mb-3">
        {item.icon ?? "✨"}
      </div>

      <h5 className="text-base md:text-lg font-semibold">{item.label}</h5>

      {item.desc && (
        <p className="text-white/75 mt-2 max-w-[40ch]">{item.desc}</p>
      )}

      {item.badges?.length ? (
        <div className="mt-2 flex flex-wrap gap-2 justify-center">
          {item.badges.map((b) => (
            <span
              key={b}
              className="text-xs bg-white/10 border border-white/10 px-2 py-0.5 rounded"
            >
              {b}
            </span>
          ))}
        </div>
      ) : null}

      <div className="mt-4">
        <CTA to={item.to} label={item.cta || "Open"} />
      </div>
    </div>
  );
}

export default function ProductsSection() {
  // Hard-wired tiles + routes so clicks always work
  const tiles = [
    {
      label: "Resume Builder",
      desc: "ATS-clean, role-targeted, practice-ready.",
      to: "/tools/resume-builder",
      icon: "📄",
      badges: ["ATS-safe", "Templates"],
      cta: "Build now",
    },
    {
      label: "Resume Quick Audit",
      // Audit-first entry point (shows QuickAudit in Builder)
      desc: "Instant ATS audit — clarity, impact & keyword coverage. No editing.",
      to: "/tools/resume-builder?mode=analyze#quick-audit",
      icon: "🩺",
      badges: ["ATS Audit", "Coverage"],
      cta: "Run Audit",
    },
    {
      label: "5-min Avatar Mock",
      desc: "Warm up with a quick, realistic voice round.",
      to: "/avatar-quick-mock",
      icon: "🎤",
      badges: ["Voice", "Quick"],
    },
    {
      label: "Interview Questions",
      desc: "Browse curated Q&A by role and company.",
      to: "/interview-questions",
      icon: "❓",
      badges: ["Role-based", "Company"],
    },
    {
      label: "Coding Problems",
      desc: "Targeted drills with editor + test cases.",
      to: "/coding-problems",
      icon: "👨‍💻",
      badges: ["DSA", "Editor"],
    },
    {
      label: "Articles",
      desc: "Short, practical reads with inline drills.",
      to: "/articles",
      icon: "🧭",
      badges: ["Guides", "Playbooks"],
    },
    {
      label: "Question of the Day",
      desc: "A fresh prompt to keep your edge sharp.",
      to: "/question-of-the-day",
      icon: "📅",
      badges: ["Daily"],
    },
    {
      label: "Task of the Day",
      desc: "One small task to build your muscle daily.",
      to: "/task-of-the-day",
      icon: "✅",
      badges: ["Daily"],
    },
  ];

  const row1 = tiles.slice(0, 3);
  const row2 = tiles.slice(3, 6);
  const row3 = tiles.slice(6, 8);

  return (
    <Section id="products">
      {/* Heading */}
      <div className="text-center mb-8 md:mb-10">
        <h2 className="text-3xl md:text-5xl font-extrabold tracking-tight">
          <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
            Open Prep Toolkit
          </span>
        </h2>
        <p className="mt-2 text-white/75 text-sm md:text-base">
          Instant, open-access tools to accelerate your prep.
        </p>
        <div className="mx-auto mt-5 h-[2px] w-28 md:w-36 bg-gradient-to-r from-transparent via-blue-300 to-transparent rounded-full" />
      </div>

      <div className="mx-auto max-w-6xl px-3 sm:px-4">
        {/* Row 1: 3 tiles */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 md:gap-6">
          {row1.map((it) => (
            <ProductCard key={it.label} item={it} />
          ))}
        </div>

        {/* Row 2: 3 tiles */}
        <div className="mt-5 md:mt-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 md:gap-6">
            {row2.map((it) => (
              <ProductCard key={it.label} item={it} />
            ))}
          </div>
        </div>

        {/* Row 3: 2 tiles centered */}
        <div className="mt-5 md:mt-6">
          <div className="flex flex-col sm:flex-row sm:justify-center gap-5 md:gap-6">
            {row3.map((it) => (
              <div key={it.label} className="sm:w-[min(28rem,42vw)] lg:w-[28rem]">
                <ProductCard item={it} />
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Hover glow */}
      <style>{`
        .product-card {
          transform: translateY(0);
          box-shadow: 0 0 0 rgba(168, 85, 247, 0);
        }
        .product-card:hover,
        .product-card:focus-within {
          transform: translateY(-2px);
          box-shadow: 0 0 18px rgba(168, 85, 247, 0.25);
          border-color: rgba(168, 85, 247, 0.38);
        }
      `}</style>
    </Section>
  );
}
