// src/pages/LaunchPage.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

import NavBar from "../NavBar.jsx";
import Chatbot from "../components/Chatbot.jsx";
import SuccessStories from "../components/SuccessStories.jsx";
import Footer from "../components/Footer.jsx";
import SignInModal from "../components/SignInModal.jsx";
import SignUpModal from "../components/SignUpModal.jsx";
import ForgotPasswordModal from "../components/ForgotPasswordModal.jsx";
import ForgotUsernameModal from "../components/ForgotUsernameModal.jsx";

import successStories from "../data/successStories.js";
import { useAuth } from "../AuthContext.jsx";

// Split components
import Hero from "../components/launch/Hero.jsx";
import MockInterviewsSection from "../components/launch/sections/MockInterviewsSection.jsx";
import ProductsSection from "../components/launch/sections/ProductsSection.jsx";
import ServicesSection from "../components/launch/sections/ServicesSection.jsx";
import ResourcesSection from "../components/launch/sections/ResourcesSection.jsx";
import CompanySection from "../components/launch/sections/CompanySection.jsx";
import PricingSection from "../components/launch/sections/PricingSection.jsx";
import ProgramIntroSections from "../components/launch/ProgramIntroSections.jsx";
import StickyActionRail from "../components/launch/StickyActionRail.jsx";
import StickySocialRail from "../components/launch/StickySocialRail.jsx";

const LaunchPage = () => {
  const navigate = useNavigate();
  const { user } = useAuth();

  const [modal, setModal] = useState(null); // 'signin' | 'signup' | 'forgot' | 'forgot-username' | null
  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
  const toggleChatbot = () => setIsChatbotOpen((v) => !v);

  const handleStart = () => {
    if (user) navigate("/mock-interview");
    else setModal("signup");
  };

  const gateTo = (path) => {
    if (user) navigate(path);
    else setModal("signup");
  };

  return (
    <div
      className="light-surface min-h-screen bg-[#FAFAF5] text-slate-900 flex flex-col overflow-x-hidden relative"
      style={{ scrollBehavior: "smooth" }}
    >
      {/* Milky background with toned-down accents for readability */}
      <div aria-hidden className="pointer-events-none absolute inset-0 -z-10">
        {/* subtle paper texture */}
        <div
          className="absolute inset-0 opacity-[0.035]"
          style={{
            backgroundImage:
              "radial-gradient(circle at 1px 1px, rgba(0,0,0,0.5) 1px, transparent 1px)",
            backgroundSize: "18px 18px",
          }}
        />
        {/* very soft color glows */}
        <div
          className="absolute -top-28 -left-28 w-[46rem] h-[46rem] rounded-full blur-3xl opacity-[0.04]"
          style={{ background: "radial-gradient(closest-side, #34d399, transparent)" }}
        />
        <div
          className="absolute bottom-[-16rem] right-[-12rem] w-[40rem] h-[40rem] rounded-full blur-3xl opacity-[0.04]"
          style={{ background: "radial-gradient(closest-side, #60a5fa, transparent)" }}
        />
        {/* gentle vignette */}
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_65%,rgba(0,0,0,.05))]" />
      </div>

      {/* Top Nav */}
      <NavBar onSignIn={() => setModal("signin")} onSignUp={() => setModal("signup")} />

      {/* Rails */}
      <StickyActionRail onGate={gateTo} hiddenOnMobile={true} />
      <StickySocialRail hiddenOnMobile={true} />

      {/* Hero */}
      <Hero onStart={handleStart} />

      {/* Program intro + sections */}
      <ProgramIntroSections />
      <MockInterviewsSection />
      <ProductsSection />
      <ServicesSection />
      <ResourcesSection />
      <CompanySection />
      <PricingSection />

      {/* Success Stories */}
      <section className="w-full py-12 md:py-16">
        <div className="max-w-7xl mx-auto px-3 md:px-6">
          <h2 className="text-2xl md:text-3xl font-bold text-slate-900 mb-6 md:mb-10">
            Success Stories
          </h2>
          <div className="w-full px-0">
            <SuccessStories stories={successStories} />
          </div>
        </div>
      </section>

      {/* Auth Modals */}
      <SignInModal
        isOpen={modal === "signin"}
        onClose={() => setModal(null)}
        onSwitchToSignUp={() => setModal("signup")}
        onSwitchToForgot={() => setModal("forgot")}
        onSwitchToForgotUsername={() => setModal("forgot-username")}
      />
      <SignUpModal
        isOpen={modal === "signup"}
        onClose={() => setModal(null)}
        onSwitchToSignIn={() => setModal("signin")}
      />
      <ForgotPasswordModal
        isOpen={modal === "forgot"}
        onClose={() => setModal(null)}
        onBack={() => setModal("signin")}
      />
      <ForgotUsernameModal
        isOpen={modal === "forgot-username"}
        onClose={() => setModal(null)}
        onBack={() => setModal("signin")}
      />

      {/* Chatbot + Footer */}
      <Chatbot isOpen={isChatbotOpen} toggleChatbot={toggleChatbot} />
      <Footer />

      {/* ===== LIGHT THEME CONTRAST RESCUE (no content changes) ===== */}
      <style>{`
        :root{
          --ts-text-strong: #0f172a;   /* slate-900 */
          --ts-text: #1f2937;          /* gray-800  */
          --ts-text-muted: #475569;    /* slate-600 */
          --ts-card-bg: rgba(255,255,255,0.96);
          --ts-card-border: rgba(2,6,23,0.08);
          --ts-card-shadow: 0 8px 28px rgba(2,6,23,0.08), 0 1px 0 rgba(2,6,23,0.05);
        }

        /* 1) Force all "white-on-dark" text to readable dark text on milky background */
        .light-surface :where(.text-white, .text-white\\/95, .text-white\\/90, .text-gray-100, .text-slate-100, .text-zinc-100, .text-neutral-100){
          color: var(--ts-text-strong) !important;
        }
        .light-surface :where(p, li, span, small, label, input, textarea, select){
          color: var(--ts-text) !important;
        }
        .light-surface :where(h1,h2,h3,h4,h5,h6,strong,b){
          color: var(--ts-text-strong) !important;
        }
        .light-surface a { color: var(--ts-text-strong) !important; text-underline-offset: 3px; }

        /* 2) Convert translucent/glassy cards to bright solid cards */
        .light-surface :where(
          .bg-white\\/5, .bg-white\\/10, .bg-white\\/20,
          .bg-black\\/10, .bg-black\\/20, .bg-black\\/30, .bg-slate-900\\/10, .bg-slate-900\\/20,
          .backdrop-blur, .backdrop-blur-sm, .backdrop-blur-md, .backdrop-blur-lg
        ){
          background-color: var(--ts-card-bg) !important;
          border: 1px solid var(--ts-card-border) !important;
          box-shadow: var(--ts-card-shadow) !important;
          backdrop-filter: saturate(140%) blur(6px);
        }

        /* 3) Buttons that were white-outline on dark: give them visible outlines */
        .light-surface :where(.border-white, .border-white\\/40, .border-white\\/60){
          border-color: var(--ts-card-border) !important;
        }
        .light-surface :where(.ring-white, .ring-white\\/40, .ring-white\\/60){
          --tw-ring-color: var(--ts-card-border) !important;
        }

        /* 4) Pills/badges that used transparent backgrounds */
        .light-surface :where(.bg-transparent, .bg-white\\/0){
          background-color: rgba(255,255,255,0.7) !important;
        }

        /* 5) Reduce any overly strong inner shadows or dark overlays from dark theme */
        .light-surface :where(.from-black\\/60, .from-slate-900\\/60, .bg-gradient-to-b){
          --tw-gradient-from: rgba(0,0,0,0.10) !important;
          --tw-gradient-stops: var(--tw-gradient-from), rgba(0,0,0,0.00);
        }

        /* Keep your existing subtle animations */
        @keyframes swirlIn {
          0% { transform: rotate(90deg) scale(0); opacity: 0; }
          50% { transform: rotate(0deg) scale(1.1); opacity: 0.5; }
          100% { transform: rotate(0deg) scale(1); opacity: 1; }
        }
        @keyframes heartbeat {
          0% { transform: scale(1); }
          10% { transform: scale(1.05); }
          20% { transform: scale(1); }
          30% { transform: scale(1.03); }
          40% { transform: scale(1); }
          100% { transform: scale(1); }
        }
        @keyframes glowPulse {
          0%   { box-shadow: 0 0 0px 0 rgba(16,185,129,0.25); }
          50%  { box-shadow: 0 0 22px 6px rgba(16,185,129,0.55); }
          100% { box-shadow: 0 0 0px 0 rgba(16,185,129,0.25); }
        }
        .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
        .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
        .glow-card { animation: glowPulse 2.4s ease-in-out infinite; border-color: rgba(16,185,129,0.45); }
        @media (prefers-reduced-motion: no-preference) {
          .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
          .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
        }
      `}</style>
    </div>
  );
};

export default LaunchPage;
