import React, { useMemo, useState } from "react";

/**
 * SummaryCard
 * -----------
 * Two render modes:
 * 1) COMPACT  -> <SummaryCard label="Package" value="40 LPA" />
 * 2) RICH     -> <SummaryCard title="Your selection" value="40 LPA" meta={{ Package:"40 LPA", ... }} ... />
 *
 * Props (rich mode):
 * - tone: "product" | "service" | "startup" | "universal" | "default"
 * - title, subtitle
 * - value: string (big headline number/text)
 * - copyValue: boolean (adds small copy button near the value)
 * - meta: { [key:string]: string }  (displayed as key→value pills)
 * - highlights: Array<{label:string, value:string, hint?:string}>
 * - bullets: string[]
 * - tags: string[]
 * - sparkline: { label?: string, data: number[] }  // drawn as inline SVG
 * - progress:  { label?: string, value: number }   // 0..100 pill
 * - actions:   { primary?: {label:string,onClick:fn}, secondary?: {label:string,onClick:fn} }
 *
 * Props (compact mode):
 * - label: string
 * - value: string
 * - tone?: (same as above)
 */

const PALETTES = {
  product:   { ring: "#10b981", ringSoft: "rgba(16,185,129,.2)", bg: "rgba(16,185,129,.08)", chip: "rgba(16,185,129,.18)" },
  service:   { ring: "#22d3ee", ringSoft: "rgba(34,211,238,.2)", bg: "rgba(34,211,238,.08)", chip: "rgba(34,211,238,.18)" },
  startup:   { ring: "#84cc16", ringSoft: "rgba(132,204,22,.2)",  bg: "rgba(132,204,22,.08)",  chip: "rgba(132,204,22,.18)" },
  universal: { ring: "#06b6d4", ringSoft: "rgba(6,182,212,.2)",   bg: "rgba(6,182,212,.08)",   chip: "rgba(6,182,212,.18)" },
  default:   { ring: "#a78bfa", ringSoft: "rgba(167,139,250,.2)", bg: "rgba(167,139,250,.08)", chip: "rgba(167,139,250,.18)" },
};

const Pill = ({ children, tone = "dim" }) => {
  const t = {
    dim:  "bg-white/8 border-white/15 text-white/90",
    soft: "bg-white/10 border-white/20 text-white",
    chip: "border-transparent",
  }[tone];
  return (
    <span className={`px-2.5 py-1 rounded-full border text-[11px] leading-none whitespace-nowrap ${t}`}>
      {children}
    </span>
  );
};

function Sparkline({ data = [], color = "#22c55e" }) {
  const points = useMemo(() => {
    if (!data.length) return "";
    // normalize into 0..1
    const max = Math.max(...data);
    const min = Math.min(...data);
    const denom = Math.max(1, max - min);
    const w = 120, h = 36, pad = 2;
    return data
      .map((y, i) => {
        const nx = pad + (i / Math.max(1, data.length - 1)) * (w - pad * 2);
        const ny = h - pad - ((y - min) / denom) * (h - pad * 2);
        return `${nx.toFixed(1)},${ny.toFixed(1)}`;
      })
      .join(" ");
  }, [data]);

  if (!points) return null;

  return (
    <svg width="120" height="36" viewBox="0 0 120 36" className="block">
      <polyline
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinejoin="round"
        strokeLinecap="round"
        points={points}
      />
    </svg>
  );
}

export default function SummaryCard(props) {
  const {
    // compact props
    label,
    value,

    // rich props
    tone = "default",
    title,
    subtitle,
    copyValue = false,
    meta = {},
    highlights = [],
    bullets = [],
    tags = [],
    sparkline,
    progress,
    actions,
  } = props;

  const pal = PALETTES[tone] ?? PALETTES.default;
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(String(value ?? ""));
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    } catch {}
  };

  // -------- COMPACT MODE --------
  if (label && !title) {
    return (
      <div
        className="rounded-2xl border border-white/10 bg-white/[0.05] p-4 relative overflow-hidden"
        style={{
          boxShadow: "inset 0 0 0 1px rgba(255,255,255,.04)",
        }}
      >
        <div
          className="absolute -right-8 -top-8 w-24 h-24 rounded-full blur-2xl opacity-25"
          style={{ background: pal.ringSoft }}
        />
        <div className="text-[11px] uppercase tracking-wide text-white/70 mb-1">{label}</div>
        <div className="flex items-center gap-2">
          <div className="text-xl font-extrabold">{value}</div>
          {copyValue && (
            <button
              onClick={handleCopy}
              className="text-[11px] px-2 py-1 rounded border border-white/15 bg-white/10 hover:bg-white/15"
              title="Copy"
            >
              {copied ? "Copied" : "Copy"}
            </button>
          )}
        </div>
      </div>
    );
  }

  // -------- RICH MODE --------
  return (
    <div
      className="rounded-3xl border border-white/10 bg-white/[0.05] p-5 md:p-6 relative overflow-hidden"
      style={{
        boxShadow:
          "inset 0 0 0 1px rgba(255,255,255,.04), 0 30px 60px rgba(0,0,0,.35)",
      }}
    >
      {/* ambient accent */}
      <div
        className="pointer-events-none absolute -right-24 -top-24 w-64 h-64 rounded-full blur-3xl opacity-25"
        style={{ background: pal.ringSoft }}
      />
      <header className="mb-4">
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div>
            <h3 className="text-base md:text-lg font-semibold">{title}</h3>
            {subtitle && (
              <p className="text-xs md:text-sm text-white/70">{subtitle}</p>
            )}
          </div>
          {(progress?.value ?? null) !== null && (
            <div className="flex items-center gap-2">
              <Pill tone="soft">
                {progress?.label ?? "Progress"}
              </Pill>
              <div className="h-2 w-28 rounded-full bg-white/10 overflow-hidden">
                <div
                  className="h-full rounded-full"
                  style={{ width: `${Math.max(0, Math.min(100, progress.value))}%`, background: pal.ring }}
                />
              </div>
            </div>
          )}
        </div>
      </header>

      {/* headline value */}
      {value && (
        <div className="flex items-center gap-3 mb-4">
          <div
            className="text-2xl md:text-3xl font-black tracking-tight"
            style={{ color: "white" }}
          >
            {value}
          </div>
          {copyValue && (
            <button
              onClick={handleCopy}
              className="text-[11px] px-2 py-1 rounded border border-white/15 bg-white/10 hover:bg-white/15"
              title="Copy"
            >
              {copied ? "Copied" : "Copy"}
            </button>
          )}
        </div>
      )}

      {/* meta pills */}
      {Object.keys(meta).length > 0 && (
        <div className="flex flex-wrap gap-2 mb-4">
          {Object.entries(meta).map(([k, v]) => (
            <Pill key={k} tone="soft">
              <span className="text-white/70 mr-1">{k}:</span>
              <b>{v}</b>
            </Pill>
          ))}
        </div>
      )}

      {/* highlights grid */}
      {highlights.length > 0 && (
        <div className="grid sm:grid-cols-3 gap-3 mb-4">
          {highlights.map((h, i) => (
            <div
              key={i}
              className="rounded-xl border border-white/10 p-3"
              style={{ background: pal.bg }}
            >
              <div className="text-[11px] uppercase tracking-wide text-white/70">
                {h.label}
              </div>
              <div className="font-semibold">{h.value}</div>
              {h.hint && (
                <div className="text-[11px] text-white/70 mt-1">{h.hint}</div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* bullets & sparkline */}
      {(bullets.length > 0 || sparkline) && (
        <div className="grid md:grid-cols-2 gap-4 mb-4">
          {bullets.length > 0 && (
            <ul className="space-y-1 text-sm">
              {bullets.map((b, i) => (
                <li key={i} className="flex gap-2">
                  <span
                    className="mt-1 inline-block h-2 w-2 rounded-full"
                    style={{ background: pal.ring }}
                  />
                  <span className="text-white/90">{b}</span>
                </li>
              ))}
            </ul>
          )}
          {sparkline && (
            <div className="rounded-xl border border-white/10 p-3 bg-white/5">
              {sparkline.label && (
                <div className="text-[11px] uppercase tracking-wide text-white/70 mb-1">
                  {sparkline.label}
                </div>
              )}
              <Sparkline data={sparkline.data} color={pal.ring} />
            </div>
          )}
        </div>
      )}

      {/* tags */}
      {tags.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-4">
          {tags.map((t, i) => (
            <span
              key={i}
              className="px-2.5 py-1 rounded-full text-[11px] border"
              style={{ background: pal.chip, borderColor: pal.ringSoft }}
            >
              {t}
            </span>
          ))}
        </div>
      )}

      {/* actions */}
      {(actions?.primary || actions?.secondary) && (
        <div className="flex flex-wrap gap-3">
          {actions?.secondary && (
            <button
              onClick={actions.secondary.onClick}
              className="px-4 py-2 rounded-full border border-white/15 bg-white/10 hover:bg-white/15 text-sm"
            >
              {actions.secondary.label}
            </button>
          )}
          {actions?.primary && (
            <button
              onClick={actions.primary.onClick}
              className="px-5 py-2 rounded-full text-sm font-semibold text-gray-900"
              style={{ background: PALETTES.product.ring }} // green CTA by default
            >
              {actions.primary.label}
            </button>
          )}
        </div>
      )}
    </div>
  );
}
