// src/components/launch/StickyActionRail.jsx
import React from "react";

/**
 * StickyActionRail
 * ----------------
 * A fixed, left-aligned vertical action rail that sticks to the viewport center.
 *
 * Props:
 *  - onGate: (path: string) => void    // auth gate callback (required)
 *  - routes?: { start: string; qotd: string; totd: string }  // optional override paths
 *  - hiddenOnMobile?: boolean          // default: true (hide on small screens to avoid covering content)
 */
export default function StickyActionRail({
  onGate,
  routes = {
    start: "/mock-interview",
    qotd: "/qotd",
    totd: "/task-of-the-day",
  },
  hiddenOnMobile = true,
}) {
  const basePos =
    "fixed left-3 md:left-4 bottom-3 md:bottom-5 z-50 flex flex-col gap-2 md:gap-3";
  const responsive = hiddenOnMobile ? "hidden md:flex" : "flex";

  const Btn = ({ label, onClick }) => (
    <button
      onClick={onClick}
      className="ts-rail-btn inline-flex items-center justify-center
                 px-4 py-2 rounded-full font-semibold text-[0.95rem] text-black
                 bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400
                 hover:from-blue-300 hover:via-blue-400 hover:to-blue-500
                 transition focus:outline-none focus-visible:ring-2
                 focus-visible:ring-blue-300/70"
      aria-label={label}
      type="button"
    >
      {label}
    </button>
  );

  return (
    <nav
      aria-label="Quick actions"
      className={`${basePos} ${responsive}`}
      style={{
        // gentle backdrop to separate from content if it overlaps
        pointerEvents: "auto",
      }}
    >
      <Btn label="Start Interview" onClick={() => onGate("/select-interview-type")} />
      <Btn label="Question of the Day" onClick={() => onGate(routes.qotd)} />
      <Btn label="Task of the Day" onClick={() => onGate(routes.totd)} />

      {/* subtle glow + lift */}
      <style>{`
        .ts-rail-btn {
          transform: translateY(0);
          box-shadow: 0 0 0 rgba(147,197,253,0);
        }
        .ts-rail-btn:hover,
        .ts-rail-btn:focus-visible {
          transform: translateY(-1px);
          box-shadow: 0 8px 22px rgba(147, 197, 253, 0.25);
        }
      `}</style>
    </nav>
  );
}
