// src/components/launch/CircularCoverflow.jsx
import React, { useEffect, useMemo, useRef, useState } from "react";

const clampMod = (n, m) => ((n % m) + m) % m;
const D2R = Math.PI / 180;
const normDeg = (deg) => ((deg + 180) % 360 + 360) % 360 - 180; // [-180, 180]

export default function CircularCoverflow({
  items = [],
  radius = 260,
  card = { w: 240, h: 160 },
  autoplayMs = 2500,
  offsetX = 0, // keep available, but use 0 for equal gaps
}) {
  const [active, setActive] = useState(0);
  const [autoPlay, setAutoPlay] = useState(true);
  const stageRef = useRef(null);

  const N = items.length || 1;
  const angleStep = 360 / N;
  const go = (steps) => setActive((a) => clampMod(a + steps, N));

  // keyboard
  const onKeyDown = (e) => {
    if (e.key === "ArrowRight") { e.preventDefault(); go(1); }
    if (e.key === "ArrowLeft")  { e.preventDefault(); go(-1); }
  };

  // drag / swipe
  const drag = useRef({ down: false, startX: 0, delta: 0 });
  const getX = (e) => ("touches" in e ? e.touches?.[0]?.clientX ?? 0 : e.clientX ?? 0);
  const onPointerDown = (e) => {
    drag.current = { down: true, startX: getX(e), delta: 0 };
    stageRef.current?.setPointerCapture?.(e.pointerId || 1);
  };
  const onPointerMove = (e) => {
    if (!drag.current.down) return;
    drag.current.delta = getX(e) - drag.current.startX;
  };
  const onPointerUp = () => {
    if (!drag.current.down) return;
    const steps = Math.round(-drag.current.delta / 120);
    if (steps) go(steps);
    drag.current = { down: false, startX: 0, delta: 0 };
  };

  // click anywhere → nearest card to center
  const onStageClick = (e) => {
    if (Math.abs(drag.current.delta) > 5) return;
    const rect = stageRef.current?.getBoundingClientRect();
    if (!rect) return;
    const centerX = rect.left + rect.width / 2 + offsetX;
    const clickX = ("clientX" in e ? e.clientX : 0) ?? 0;
    const relX = clickX - centerX;

    let target = active, best = Infinity;
    for (let i = 0; i < N; i++) {
      const theta = normDeg(angleStep * (i - active));
      const x = radius * Math.sin(theta * D2R);
      const d = Math.abs(x - relX);
      if (d < best) { best = d; target = i; }
    }
    setActive(target);
  };

  // auto-spin (pauses on hover/focus; respects reduced motion)
  useEffect(() => {
    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce || !autoPlay) return;
    const id = setInterval(() => go(1), autoplayMs);
    return () => clearInterval(id);
  }, [autoPlay, autoplayMs]);

  const cards = useMemo(() => {
    return items.map((title, i) => {
      const theta = normDeg(angleStep * (i - active));
      const rad = theta * D2R;

      // flat horizontal rail (active at x=0)
      const x = radius * Math.sin(rad);
      const y = 0;

      // depth & focus
      const focus   = Math.cos(rad);
      const scale   = 0.75 + 0.25 * Math.max(0, focus);
      const opacity = 0.50 + 0.50 * Math.max(0, focus);
      const z       = 1000 + Math.round(1000 * Math.max(-0.2, focus));
      const tilt    = -0.45 * theta;

      const isActive = i === active;

      // Center each card on the stage center, THEN move along the rail.
      const transform = `
        translate(-50%, -50%)
        translate3d(${x + offsetX}px, ${y}px, 0)
        rotateY(${tilt}deg)
        scale(${scale})
      `;

      // ✨ Gold glow for the active card
      const glowShadow = isActive
        ? "0 0 0 2px rgba(255,215,0,0.35), 0 0 32px 10px rgba(253,224,71,0.55), 0 0 68px 20px rgba(245,158,11,0.40)"
        : "0 6px 18px rgba(0,0,0,0.35)";

      return (
        <button
          key={i}
          type="button"
          className={
            "absolute rounded-2xl overflow-hidden text-gray-900 transform-gpu will-change-transform " +
            (isActive ? "ring-2 ring-amber-300/90" : "ring-1 ring-amber-200/30") +
            " shadow-xl focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-300"
          }
          style={{
            left: "50%",  // anchor card center on stage center
            top: "50%",
            width: card.w,
            height: card.h,
            transform,
            zIndex: z,
            opacity,
            boxShadow: glowShadow,
            transition: "transform 420ms cubic-bezier(0.22,1,0.36,1), opacity 260ms, box-shadow 320ms",
            // 🟡 Gold gradient background (warm, metallic feel)
            backgroundImage:
              "linear-gradient(135deg, rgba(253,224,71,1) 0%, rgba(245,158,11,1) 60%, rgba(234,179,8,1) 100%)",
          }}
          aria-label={String(title)}
          aria-current={isActive ? "true" : undefined}
          onClick={() => setActive(i)}
        >
          <div className="h-full w-full flex items-center justify-center p-5 text-center">
            <h3 className="text-base font-semibold leading-snug drop-shadow-[0_1px_0_rgba(255,255,255,0.35)]">
              {title}
            </h3>
          </div>
        </button>
      );
    });
  }, [items, active, angleStep, radius, card.w, card.h, offsetX]);

  if (!items.length) return null;

  return (
    <section
      className="relative w-full h-[220px] md:h-[240px] flex items-center justify-center"
      role="region"
      aria-roledescription="carousel"
      aria-label="Circular coverflow"
      tabIndex={0}
      onKeyDown={onKeyDown}
    >
      {/* Stage */}
      <div
        ref={stageRef}
        className="relative w-full h-full mx-auto flex items-center justify-center"
        style={{ perspective: 1200, maxWidth: "1100px" }}
        onPointerDown={(e) => { setAutoPlay(false); onPointerDown(e); }}
        onPointerMove={onPointerMove}
        onPointerUp={(e) => { onPointerUp(e); setAutoPlay(true); }}
        onPointerCancel={(e) => { onPointerUp(e); setAutoPlay(true); }}
        onMouseEnter={() => setAutoPlay(false)}
        onMouseLeave={() => setAutoPlay(true)}
        onFocus={() => setAutoPlay(false)}
        onBlur={() => setAutoPlay(true)}
        onClickCapture={onStageClick}
      >
        {cards}
      </div>

      <p className="sr-only" aria-live="polite">
        {`Item ${active + 1} of ${N}: ${items[active]}`}
      </p>
    </section>
  );
}
